def decimal_to_binary(decimal):
    """Converts a decimal number to binary."""
    if decimal == 0:
        return "0"
    else:
        binary = ""
        while decimal > 0:
            binary = str(decimal % 2) + binary
            decimal //= 2
        return binary

def binary_to_decimal(binary):
    """Converts a binary number to decimal."""
    return int(binary, 2)

def main():
    while True:
        user_input = input("Enter 'dec' to convert from decimal to binary, or 'bin' to convert from binary to decimal: ").lower()
        if user_input == "dec":
            decimal = int(input("Enter a decimal number: "))
            print(decimal_to_binary(decimal))
        elif user_input == "bin":
